          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"6d604853-d4d3-576b-ad5d-7f0e374b6bc8","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطاردة -عدم التجاوب مع السلطات -هروب من نقطة التفتيش -تلفيات -تعهد -حدث -تعزير باجللد والسجن .","document_number":"34279959","case_number":"34150676","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/25","year":"1434","subject":"مطاردة -عدم التجاوب مع السلطات -هروب من نقطة التفتيش -تلفيات -تعهد -حدث -تعزير باجللد والسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34279959:‬تاريخه‪1434/07/25 :‬هـ‬\n                          ‫رقم الدعوى‪34150676:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34302495‬تاريخه‪1434/08/22:‬هـ‬\n\n\n       ‫مطــاردة ‪ -‬عــدم التجــاوب مــع الســلطات ‪ -‬هــروب مــن نقطــة التفتيــش‬\n                      ‫‪ -‬تلفيــات ‪ -‬تعهــد ‪ -‬حــدث ‪ -‬تعزيــر باجللــد والســجن ‪.‬‬\n\n\n\n\n       ‫ض َب ْعـ َـد ِإ ْص َل ِح َهــا)) وقــال تعالــى ‪:‬‬               ‫‪ -‬قــال تعالــى‪َ (( :‬و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                                                                 ‫ال ْر ِ‬\n                                                           ‫الل ال ُي ِ ُّحــب ْالُ ْع َتدِ َيــن)) ‪.‬‬ ‫(( َوال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n       ‫((كل املســلم علــى املســلم حــرا ٌم‬                 ‫ُّ‬         ‫‪ -‬قــال صلــى اهلل عليــه وســلم ‪:‬‬\n       ‫كـ ْـم‬‫وعرضــه)) وقــال عليــه الصــاة والســام ‪((:‬فَ ـ ِإ َّن د َِم َاء ُ‬                         ‫ُ‬          ‫دم ـ ُه وما ُل ـ ُه‬   ‫ُ‬\n       ‫ك ْم‬ ‫ك ُح ْر َمـ ِة َي ْومِ ُكـ ْـم َه َذا ‪ِ ،‬ف َشــهْ ِر ُ‬‫اض ُكـ ْـم َحـ َـرا ٌم َع َل ْي ُكـ ْـم َ‬‫َوأ َْم َوا َل ُكـ ْـم َوأَعْ َر َ‬\n                                                                                       ‫كـ ْـم َهـ َـذا)) ‪.‬‬   ‫َهـ َـذا ‪ِ ،‬ف َب َلدِ ُ‬\n\n\n\n\n       ‫‪-‬اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بالهــروب مــن نقطــة تفتيــش‬\n       ‫وصــدم الدوريــة األمنيــة يطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n       ‫بعقوبــة تأديبيــة تقــوم ســلوكه‪ .‬وبضبــط أقــوال قائــد الدوريــة األمنيــة أنه‬\n       ‫بتاريــخ ‪1434/12/28‬ه ـ مــر عليــه بنقطــة التفتيــش املشــتركة ســيارة‬\n       ‫مــن نــوع ‪ ...‬موديــل اللــون أبيــض رقــم اللوحــة (‪ )....‬وبهــا ثالثــة أشــخاص‬\n       ‫وكانــت الســيارة تســير بنحــو (م ‪/140‬كــم) يف الســاعة وقــام هــو‬\n       ‫وزمــاؤه مبتابعتهــم ومطاردتهــم بثــاث دوريــات ارتطمــت الســيارة مــع‬\n\n‫‪301‬‬\n\f    ‫دوريــة مســاندة ومت القبــض عليهــم وإحضارهــم ملركــز الشــرطة ‪.‬‬\n‫وباســتجواب املدعــى عليــه‪ :‬أفــاد بأنــه أقــدم علــى الهــرب مــن نقطــة‬\n‫تفتيــش أثنــاء قيادتــه ســيارة شــقيقه املدعــو ‪ ...‬وذلــك لعــدم حملــه رخصــة‬\n‫قيــادة وكان شــقيقه ‪ ...‬يرافقــه ‪ -‬ثبــوت إدانــة املدعــى عليــه واحلكــم‬\n‫عليــه بالســجن واجللــد وأخــذ التعهــد ‪ -‬صــدق احلكــم مــن محكمــة‬\n                                                                   ‫االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي انــا القاضــي باحملكمــة اجلزائيــة باألحســاء‬\n‫ـاء علــى املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واإلدعــاء العــام‬\n                                                                              ‫بنـ ً‬\n‫مبحافظــة األحســاء برقــم ‪ 4771‬وتاريــخ ‪1434/4/1‬ه ـ واملقيــدة بهــذه‬\n‫احملكمــة برقــم ‪ 34802224‬وتاريــخ ‪1434/4/2‬ه ـ واحملالــة إلينــا مــن‬\n‫فضيلــة الرئيــس برقــم ‪ 34150676‬وتاريــخ ‪1434/4/2‬ه ـ وفيهــا حضــر‬\n‫املدعــي العــام ‪ ....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n‫خطــاب ســعادة رئيــس دائــرة التحقيــق واإلدعــاء العــام مبحافظــة‬\n‫األحســاء ذي الرقــم ‪ 13415‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه‬\n‫ا بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام مبحافظــة األحســاء‬ ‫قائـ ً‬\n‫أدعــي علــى‪ ............/‬احلــدث‪ ، ..../‬البالــغ من العمر(‪ )17‬عام ًا ‪ ،‬ســعودي‬\n‫اجلنســية مبوجب الســجل املدني رقم (‪ ) ....‬أوقف بتاريخ‪1434/1/29‬هـ‬\n‫وأفــرج عنــه بالكفالــة بتاريــخ ‪1434/2/3‬ه ـ إنه بتاريــخ ‪1434/1/28‬هـ‬\n‫ورد لشــرطة األحســاء تقريــر الدوريــات األمنيــة املتضمــن أنهــم أثنــاء‬\n‫القيــام بعملهــم عنــد نقطــة التفتيــش بالقــرب مــن دوار الوفــرة وتزامــن‬\n‫ذلــك مــع مــرور ســيارة مــن نــوع ‪....‬موديــل (‪2002‬م) اللــون أبيــض رقــم‬\n\n                                                                                      ‫‪302‬‬\n\f      ‫اللوحــة (‪ ).. ..‬بقيــادة املدعــى عليــه وبهــا ثالثــة أشــخاص وكانــت‬\n      ‫الســيارة تســير بنحــو (م ‪/140‬كــم) فطلــب منهــم الوقــوف ولــم يتوقفــوا‬\n      ‫عنــد نقطــة التفتيــش فقامــت الدوريــات األمنيــة مبتابعتهــم ومطاردتهــم‬\n      ‫بثــاث دوريــات وعنــد دوار املراعــي قــام صاحــب الســيارة مبســك فرامــل‬\n      ‫ممــا أدى إلــى اصطــدام الدوريــة بالرصيــف حتــى توقــف وعنــد منزلهــم‬\n      ‫الكائــن بحــي ‪ ............‬ترجــل مــن الســيارة خمســة أشــخاص اثنــان منهــم‬\n      ‫هربــوا والباقــي قامــوا مبقاومــة رجــال األمــن وقامــوا بإدخــال الســيارة‬\n      ‫إلــى داخــل املنــزل فتــم القبــض علــي املدعــى عليــه وبرفقتــه شــقيقه‬\n         ‫(أفــرزت لــه أوراق مســتقلة وتعالــج لــدى شــرطة محافظــة األحســاء)‪.‬‬\n      ‫‪.‬وباالنتقــال إلــى موقــع حــادث صــدم الدوريــة ملعاينتــه تبــن انــه يقــع بحــي‬\n      ‫‪ ........‬قبــل محطــة ‪ ........‬حيــث اتضــح أنهــا دوريــة أمنيــة نــوع (أف جــي)‬\n      ‫حتمــل اللوحــة رقــم(‪). . .‬موديــل(‪2010‬م) مصدومــة مــن جهــة الدعامــة‬\n                            ‫ألماميــة ومعطوبــة مــن جهــة اإلطــار األيســر األمامــي‪.‬‬\n      ‫وبضبــط أقــوال قائــد الدوريــة األمنيــة‪ .... /‬انــه بتاريــخ ‪1434/12/28‬ه ـ‬\n      ‫مر عليه بنقطة التفتيش املشتركة سيارة من نوع ‪ ......‬موديل (‪2002‬م)‬\n      ‫اللــون أبيــض رقــم اللوحــة (‪ )...‬وبهــا ثالثــة أشــخاص وكانــت الســيارة‬\n      ‫تســير بنحــو (م ‪/140‬كــم) يف الســاعة وقــام هــو وزمــاءه مبتابعتهــم‬\n      ‫ومطاردتهــم بثــاث دوريــات وعنــد دوار املراعــي ارتطمــت الســيارة‬\n      ‫مــع دوريــة مســاندة والتــي يقودهــا ‪ ............‬بعــد أن أمســك الفرامــل‬\n      ‫قائــد الســيارة ممــا أدى إلــى االصطــدام والهــرب وكان قائــد الدوريــة‬\n      ‫املذكــور أعــاه خلــف صاحــب الســيارة حتــى توقــف وعنــد منزلهــم‬\n      ‫الكائــن بحــي ‪ ............‬وقامــوا بإدخــال الســيارة إلــى داخــل املنــزل وبعــد‬\n      ‫عشــرون دقيقــة خــرج األشــخاص الذيــن كانــوا بالســيارة ومت القبــض‬\n\n\n‫‪303‬‬\n\f‫عليهــم وإحضارهــم ملركــز الشــرطة وقــام أحدهــم بتهديــده مبســك‬\n‫يــده وتهديــده بقولــه (لــو أخــرج مــن الســجن بعــد عشــر ســنوات ســأقوم‬\n‫بذبحــك) وباســتجواب املدعــى عليــه‪ :‬أفــاد بأنــه أقــدم علــى الهــرب مــن‬\n‫نقطــة تفتيــش أثنــاء قيادتــه ســيارة شــقيقه املدعــو‪ ... /‬وذلــك لعــدم حملــه‬\n‫رخصــة قيــادة وكان شــقيقه ‪ ..‬يرافقــه وقــد طاردتــه الدوريــات األمنيــة‬\n‫وعندمــا حــاول أخــذ لفــة مت صدمــه مــن قبــل الدوريــة األمنيــة مــن اخللــف‬\n                       ‫كونــه أمســك الفرامــل ‪ ،‬هــذا مــا حــدث علم ـ ًا بأنــه‪.‬‬\n‫وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بالهــروب مــن نقطــة‬\n   ‫تفتيــش وصــدم الدوريــة األمنيــة ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة‪-:‬‬\n‫‪ -1‬إقــرار املدعــى عليــه املصــادق عليــه شــرعا املــدون علــى الصفحــة‬\n                            ‫رقــم(‪ )7‬مــن ملــف التحقيــق املرفــق لفــة رقــم(‪.)1‬‬\n‫‪ -2‬محضــر تنفيــذ مهمــة وتســليمها جلهــة االختصــاص املرفــق لفــة‬\n                                                         ‫ر قــم(‪.)13-12-11-10‬‬\n                              ‫‪ -3‬محضر االنتقال واملعاينة املرفق لفة رقم(‪.)3‬‬\n                                  ‫‪ -4‬إفادة رجل األمن املرفقة لفة رقم(‪.)6-5-4‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n‫أطلــب إثبــات مــا أســند إليــه واحلكم عليه بعقوبة تأديبية تقوم ســلوكه‪.‬‬\n                                             ‫(علما بان احلق اخلاص مازال قائما)‬\n‫هكــذا ا َّدعــى ؛ وعليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن‬\n‫ا ‪ :‬ماذكــره‬    ‫هويتــه جــرى عــرض دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n‫املدعــي العــام مــن اتهامــي بالهــروب مــن رجــال األمــن ممــا أ َّدى إلــى‬\n‫ـادم علــى مابــدر منــي‬ ‫اصطــدام الدوريــة األمنيــة بــي فصحيــح وأنــا نـ ٌ‬\n‫هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪:‬‬\n\n\n                                                                                     ‫‪304‬‬\n\f      ‫ـاء‬\n        ‫كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق عليــه فبنـ ً‬\n      ‫علــى ماتقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى عليــه‬\n      ‫أن املدعى‬          ‫والتأكد من أهليته وبعد دراســة أوراق املعاملة وتأملها ومبا َّ‬\n      ‫عليــه أقـ َّـر بدعــوى املدعــي العــام وأنــه قــام بالهــروب مــن رجــال األمــن مما‬\n      ‫أن ماصــدر منــه مــن احملـ َّـرم شــرع ًا‬                   ‫أ َّدى إلــى اصطــدام الدوريــة بــه ومبــا َّ‬\n      ‫(وال‬   ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا) وقــال تعالــى ‪َ :‬‬             ‫ال ْر ِ‬  ‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬   ‫قــال تعالــى‪َ :‬‬\n         ‫الل ال ُي ِ ُّحــب ْال ُْع َتدِ َيــن) وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ‬                            ‫َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫وعرضــه)) وقــال عليــه الصــاة‬               ‫ُ‬             ‫دم ـ ُه وما ُل ـ ُه‬  ‫ـرام ُ‬\n                                                                                            ‫املســلم علــى املســلم حـ ٌ‬\n      ‫كـ ْـم‬   ‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬‫اض ُ‬‫َكـ ْـم َو َأ ْع َر َ‬   ‫كـ ْـم َو َأ ْم َوال ُ‬‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                                                                                                     ‫والســام َ‬\n      ‫كـ ْـم َهـ َـذا )) ممــا‬        ‫ك ْم َهـ َـذا ‪ِ ،‬ف َبلَدِ ُ‬        ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬     ‫ك ُح ْر َمـ ِة َي ْومِ ُ‬    ‫َ‬\n      ‫يســتوجب تعزيــر املدعــى عليــه ويتوجــه تخفيــف العقوبــة لصغــر ســنه‬\n      ‫ولعــدم وجــود ســوابق عليــه ولظهــور آثــار النــدم والتوبــة عليــه لــذا كلــه‬\n      ‫لدي‬  ‫وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبت َّ‬\n      ‫إدانــة املدعــى عليــه بالهــروب مــن رجــال األمــن ممــا أ َّدى إلــى اصطــدام‬\n      ‫الدوريــة بــه وعزرتــه لقــاء ذلــك بســجنه ثالثــة أشــهر حتتســب منهــا املــدة‬\n      ‫التــي أوقــف فيهــا علــى ذمــة القضيــة وبجلــده مائة وخمســون جلدة مفرقة‬\n      ‫علــى ثــاث دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى‬\n      ‫مــدة التقــل عــن عشــرة أيــام ‪ .‬ثاني ـ ًا ‪ /‬يؤخــذ عليــه التعهــد بعــدم العــودة‬\n      ‫ملثــل ماصــدر منــه ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليــه‬\n      ‫بحقــه يف اســتئناف احلكــم قــرر قناعتــه بــه وطلــب املدعــي العــام رفــع‬\n      ‫كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة‬\n      ‫اعتراضيــة مكتفيـ ًا مبــاورد يف الئحــة الدعــوى وصلــى اهلل وسـلَّم علــى‬\n                ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعني‪.‬حــرر يف ‪1434/7/25‬هــ‪.‬‬\n\n\n‫‪305‬‬\n\f‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n     ‫بقرارهــا رقــم ‪ ........‬يف ‪ .......‬ومضمــون املصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n                                                                               ‫‪306‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":301,"source_page_end":306,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"825e58ad8d80319c07d1ac50ca9138cdcf669c9ea066929346a5fcdf2dcfc969","normalized_text_hash":"b6e987e799bfc60112295aca1ad1f0e05b7f338107017e1801c1f1ffd7794cef","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p301-34279959"},{"id":"7e0ca38c-b8d4-55e3-8acf-8926ef65d3d4","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء على رجل األمن -إتاف ممتلكات عامة -هروب من دورية أمنية -ثبوت -إقرار -تعزير بالسجن واجللد.","document_number":"34233346","case_number":"34253560","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/06","year":"1434","subject":"اعتداء على رجل األمن -إتاف ممتلكات عامة -هروب من دورية أمنية -ثبوت -إقرار -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34233346:‬تاريخه‪1434/06/06 :‬هـ‬\n                           ‫رقم الدعوى‪34253560:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                        ‫‪1434/09/03: 34312352‬ه‬\n\n\n       ‫اعتــداء علــى رجــل األمــن ‪ -‬إتــاف ممتلــكات عامــة ‪ -‬هــروب مــن دوريــة‬\n                              ‫أمنيــة ‪ -‬ثبــوت ‪ -‬إقــرار ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n                                        ‫‪ -‬للقاعدة الشرعية ‪« :‬ال عذر ملن أقر» ‪.‬‬\n                          ‫‪ -‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n\n\n\n\n       ‫أقــام املدعــى العــام دعــواه ضــد املدعــى عليــه يطلــب احلكــم عليــه بعقوبة‬\n       ‫تعزيريــة حيــث أنــه قــام بصــدم دوريــة أمنيــة مما تســبب يف إصابة قائدها‬\n       ‫وإتــاف ممتلــكات عامــة والهــرب مــن املوقــع ومبواجهــة املدعــى عليــه‬\n       ‫بالدعــوى أقــر مبــا فيهــا وعليــه قــررت احملكمــة ســجنه ملــدة شــهرين‬\n       ‫وجلــدة خمســن جلــدة وأخــذ التعهــد عليــه بعــدم العــودة ملثــل ذلــك وقــرر‬\n            ‫املدعــى العــام االعتــراض وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n       ‫مبكــة املكرمــة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n\n‫‪307‬‬\n\f‫احملكمــة اجلزائيــة مبكــة املكرمــة برقــم ‪ 34253560‬وتاريــخ‬\n‫‪ 1434/06/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341337178‬وتاريــخ‬\n‫‪ 1434/06/04‬ه ـ ففــي يــوم اإلثنــن املوافــق‪ 1434/06/05‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 01 : 45‬وفيهــا حضــر املدعــي العــام ‪............‬وادعــى‬\n‫علــى احلاضــر معــه ‪...............‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫ا يف دعــواه عليــه انــه بتاريــخ ‪1434/4/3‬ه ـ تبلغــت‬            ‫رقــم (‪ ).........‬قائ ـ ً‬\n‫الدوريــات األمنيــة عــن وجــود حالــة صــدم عمــد لدوريــة املــرور الســرية‬\n‫وبالشــخوص إلــى املوقــع وجــد رجــل األمــن ‪ .........../‬مفيــد ًا بــأن املدعــى‬\n‫عليــه قــام بصــدم الســيارة األمنيــة عمــد ًا وهــرب مــن املوقــع بعــد أن‬\n‫احــدث تلفيــات بالســيارة األمنيــة ( مت إنهــاء موضوعهــا ) واحــدث إصابــة‬\n‫يف رجــل األمــن وصــدر لــه التقريــر الطبــي ( ‪ )494‬يف ‪1434/4/3‬ه ـ‬\n  ‫املتضمــن وجــود رضــه بالســاعد األيســر ومــدة الشــفاء خمســة أيــام ‪.‬‬\n‫وبضبــط أقــوال رجــل األمــن أفــاد بــأن املدعى عليــه مت إيقافه اثر مخالفة‬\n‫مروريــة وهــي طمــس لوحــة الســيارة التــي يقودهــا ثــم بعــد أن اخــذ إثباتــه‬\n‫طلــب منــه مرافقتــه للحجــز املــروري لكــي يتــم حجــز الســيارة وأثنــاء‬\n‫ذلــك قــام بصــدم الســيارة األمنيــة والهــرب مــن املوقــع ونتــج عــن ذلــك‬\n                      ‫بعــض التلفيــات بالســيارة واإلصابــات يف رجــل األمــن ‪.‬‬\n‫وباســتجواب املدعــى عليــه اعتــرف بأنــه قــام بصــدم الســيارة األمنيــة‬\n                                                                ‫والهــرب مــن املوقــع ‪.‬‬\n‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه بصــدم الدوريــة‬\n‫األمنيــة ممــا تســبب يف اصابــة قائدهــا واتالف ممتلــكات عامة والهرب‬\n                                    ‫مــن املوقــع « وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n                                 ‫‪ -1‬اعترافه املدون لفة رقم ( ‪ )37‬ولفة ( ‪. )38‬‬\n\n\n                                                                                              ‫‪308‬‬\n\f                                  ‫‪ -2‬احملاضر األمنية لفة رقم ( ‪ )2‬و ( ‪ )7‬و ( ‪. ) 8‬‬\n                                                      ‫‪ -3‬التقرير الطبي لفة رقم (‪. )13‬‬\n      ‫حيــث أن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم ومعاقــب عليــه‬\n      ‫شــرعا لــذا أطلــب إثبــات مــا اســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة‪-‬‬\n      ‫لقــاء ذلــك والتشــديد عليــه وفقــا لتعميــم صاحــب الســمو امللكــي النائــب‬\n      ‫الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة رقــم ‪36717/3/5/1‬‬\n                                                              ‫وتاريــخ ‪1432 / 6 /11‬ه ـ ‪.‬‬\n      ‫( علمــا بــان احلــق اخلــاص انتهــى بالتنــازل) ‪ .‬هــذه دعــواي وبعــرض دعــوى‬\n      ‫ا ماذكــره املدعــي العــام يف‬    ‫املدعــي العــام علــى املدعــى عليــه أجــاب قائـ ً‬\n      ‫دعــواه صحيــح هــذه إجابتــي فبعــد مــا ســلف مــن الدعــوى واإلجابــة وبعــد‬\n      ‫اإلطــاع علــى محضــر القبــض واإلســتجواب والتقريــر الطبــي املتضمــن‬\n      ‫إصابــة رجــل األمــن بإصابــات وقــدرت مــدة الشــفاء خمســة أيــام وإلقــرار‬\n      ‫املدعــى عليــه بجميــع مــا نســب إليــه يف دعــوى املدعــي العــام وللقاعــدة‬\n      ‫الشــرعية ال عــذر ملــن أقــر وحلرمــة مــا أقــدم عليــه يف الشــريعة اإلســامية‬\n      ‫لقولــة تعالــى ( وال تعتــدوا إن اهلل ال يحــب املعتديــن ) وألنــه يســتحق‬\n      ‫العقوبــة التعزيريــة علــى مــا بــدر منــه ونظــر ًا لتنــازل احلــق اخلــاص عــن‬\n      ‫دعــواه حســب مــا يتضــح مــن الئحــة الدعــوى العامــة ملــا ســبق كلــه فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه وعزرتــه لقــاء ذلــك بســجنه‬\n      ‫ملــدة شــهرين حتتســب مــن تاريــخ إيقافــه وجلــده خمســن جلــدة دفعــة‬\n      ‫واحــدة وأخــذ التعهــد عليــه بعــدم العــودة ملثــل ذلــك هــذا مــا ظهــر لــي وبــه‬\n      ‫حكمــت وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة كمــا قــرر‬\n      ‫املدعــي العــام اإلعتــراض بالئحــة ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n                                              ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n‫‪309‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ :‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة الثالثــة مبحكمــة االســتئناف‬\n‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة إلينــا شــفع‬\n‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة مبكــة املكرمــة رقــم‬\n‫‪341337178‬وتاريــخ ‪1434/8/23‬ه ـ املشــتملة علــى القــرار الصــادر مــن‬\n‫فضيلــة الشــيخ‪........... /‬القاضــي باحملكمــة اجلزائيــة مبكــة املكرمــة‬\n‫املــؤرخ يف ‪1434/6/6‬ه ـ واملســجل بعــدد ‪ ، 34233346‬املتضمــن دعــوى‬\n‫املدعــي العــام ضــد‪......... /‬املتهــم بصــدم الدوريــة األمنيــة ممــا تســبب يف‬\n‫اصابــة قائدهــا واتــاف ممتلــكات عامــة والهــرب مــن املوقــع احملكــوم‬\n‫فيــه مبــا ّدون بباطــن القــرار وبدراســة القــرار وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n                                       ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n\n\n\n\n                                                                                      ‫‪310‬‬\n\f311\n\f312\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":307,"source_page_end":312,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3054e58204fcb4654ec54c34129dada6cad618a52301d30824b3e03da873773d","normalized_text_hash":"e31db17465833e63a77aa5a93b628b9da231f7ebc0aa13258bc1e9ae935d671d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p307-34233346"},{"id":"9b6fc109-91dd-5259-a9cb-9920126d8213","document_type":"judgment","category":"judicial","subcategory":"general","title":"املجاهرة بالفطر يف نهار رمضان -اجلمع بن جرمن .جرم انتهاك حرمة الزمان باإلفطار يف نهار رمضان بدون عذر شرعي وجرم املجاهرة باملعصية -التعزير باجللد علن ا والتوبيخ وأخذ التعهد -قوله صلى اهلل عليه وسلم ( :كل أمتي معافى إال املجاهرين)","document_number":"34266487","case_number":"32427909","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية على املعاملة املقيدة لدى المحكمة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/10/06","year":"1434","subject":"املجاهرة بالفطر يف نهار رمضان -اجلمع بن جرمن .جرم انتهاك حرمة الزمان باإلفطار يف نهار رمضان بدون عذر شرعي وجرم املجاهرة باملعصية -التعزير باجللد علن ا والتوبيخ وأخذ التعهد -قوله صلى اهلل عليه وسلم ( :كل أمتي معافى إال املجاهرين)","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34266487 :‬تاريخه‪1432/10/06 :‬هـ‬\n                           ‫رقم الدعوى‪32427909:‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n         ‫االستئناف‪ 34300844:‬تاريخه‪1434/8/21 :‬هـ‬\n\n\n       ‫املجاهــرة بالفطــر يف نهــار رمضــان‪ -‬اجلمــع بــن جرمــن‪ .‬جــرم انتهــاك‬\n       ‫حرمــة الزمــان باإلفطــار يف نهــار رمضــان بــدون عــذر شــرعي وجــرم‬\n       ‫املجاهــرة باملعصيــة ‪ -‬التعزيــر باجللــد علن ـ ًا والتوبيــخ وأخــذ التعهــد‬\n\n\n\n       ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ‪( :‬كل أمتــي معافــى إال املجاهريــن)‬\n                                                                ‫متفــق عليــه‪.‬‬\n\n\n\n\n       ‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهــم (أربعــة رجــال)‬\n       ‫باملجاهــرة بالفطــر يف نهــار رمضــان‪ -‬طلــب املدعــي العــام إثبــات مــا‬\n       ‫أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة ‪ -‬بعــرض دعــوى املدعــي‬\n       ‫العــام علــى املدعــى عليهــم األول والثالــث والرابــع بواســطة املترجــم‪،‬‬\n       ‫صادقــوا عليهــا‪ ،‬وقــرروا أن ديانتهــم اإلســام‪ ،‬وبعــرض الدعــوى‬\n       ‫علــى املدعــى عليــه الثانــي أنكرهــا‪ ،‬وقــرر أنــه كان جالســا مــع بقيــة‬\n       ‫املدعــى عليهــم ولــم يفطــر وأنكــر عليهــم فطرهــم‪ -‬قــرر املدعــى عليهــم‬\n       ‫األول والثالــث والرابــع أن املدعــى عليــه الثانــي لــم يقــم بالفطــر معهــم‬\n       ‫وأنــه نصحهــم وقــرروا توبتهــم وندمهــم‪ -‬جــرى االطــاع علــى محضــر‬\n       ‫القبــض وبعرضــه علــى املدعــى عليــه الثانــي أنكــره ‪ -‬نظــر ًا ألن املدعــى‬\n\n‫‪313‬‬\n\f‫عليهــم األول والثالــث والرابــع أقــروا بدعــوى املدعــي العــام وأنكرهــا‬\n‫املدعــي عليــه الثانــي وحيــث ال يوجــد لــدى املدعــي العــام بينــة‪ ،‬ولكــون‬\n‫الصيــام مــن أعظــم الفرائــض التــي كتبهــا اهلل ســبحانه علــى عبــاده‬\n‫املوحديــن‪ ،‬ونظــرا لكــون املدعــى عليهــم قــد جمعــوا بــن جرمــن جــرم‬\n‫انتهــاك حرمــة الزمــان وذلــك باإلفطــار يف نهــار رمضــان بــدون عــذر‬\n‫شــرعي وجــرم املجاهــرة باملعصيــة لذلــك ثبتــت إدانــة املدعــى عليهــم‬\n‫األول والثالــث والرابــع باملجاهــرة بالفطــر يف نهــار رمضــان بــدون عــذر‬\n‫شــرعي ونظــرا لكــون املدعــى عليهــم ال يوجــد عليهــم ســوابق وأبــدو‬\n‫التوبــة والنــدم لــذا فقــد مت احلكــم بجلــد كل واحــد منهــم ثالثــن جلــدة‬\n‫علنــا ولــم يثبــت إدانــة املدعــى عليــه الثانــي مبــا نســب إليــه إال أن التهمــة‬\n‫تتوجــه نحــوه ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق وملــا‬\n‫ذكــره أنــه قــام باإلنــكار علــى املدعــى عليهــم حــن مجاهرتهــم بالفطــر‬\n‫ولكــون التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل حســبما نــص عليــه أهــل‬\n‫العلــم لــذا فقــد مت توبيــخ املدعــى عليــه وإفهامــه مبغبــة عملــه مــع أخــذ‬\n‫التعهــد الشــديد علــى املدعــى عليهــم ‪-‬جــرى إفهــام املدعــى عليهــم بــأن‬\n‫عليهــم التوبــة إلــى اهلل وقضــاء هــذا اليــوم الــذي أفطــروا فيــه وبعــرض‬\n‫احلكــم علــى املدعــى عليهــم قــرروا القناعــة بــه كمــا قــرر املدعــي العــام‬\n‫املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة الدعــوى عــن تقــدمي الئحــة‬\n‫اعتراضيــة‪ ،‬وبعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة‬\n                                                                                ‫عليــه‪.‬‬\n\n\n\n\n                                                                                          ‫‪314‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنا‪......‬املــازم القضائــي باحملكمــة‬\n      ‫اجلزائيــة باألحســاء يف املكتــب القضائــي الســادس وبنــاء علــى املعاملــة‬\n      ‫احملالــة مــن رئيــس احملكمــة اجلزائيــة باألحســاء برقــم (‪)32427909‬‬\n      ‫يف ‪1432/10/6‬ه ـ واملقيــدة برقــم (‪ )321234605‬يف ‪1434/10/6‬ه ـ‬\n      ‫وبنــاء علــى تعميــدي مــن فضيلــة الشــيخ‪....../‬رئيس احملكمــة‬\n      ‫اجلزائيــة باألحســاء املكلــف مبوجــب خطابــه رقــم (‪ )34970436‬يف‬\n      ‫‪1434/4/21‬ه ـ لنظــر القضايــا مــا عــدا الســجناء ويف يــوم األحــد‬\n      ‫املوافــق ‪1434/4/12‬ه ـ افتتحــت اجللســة األولــى يف متام الســاعة التاســعة‬\n      ‫وخمــس واربعــن دقيقــة يف هــذه القضيــة رقــم (‪ )3238800734‬وفيهــا‬\n      ‫حضــر املدعــي العــام ‪......‬الســعودي بالســجل املدنــي رقــم (‪ )......‬وحضــر‬\n      ‫حلضــوره املدعــى عليهــم وبســؤال املدعــي العــام عــن دعــواه قــال بصفتــي‬\n      ‫مدعيــا عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى‪/‬‬\n      ‫‪......‬باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة مــن الهفــوف برقــم‬\n      ‫(‪ )......‬و‪......‬باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة مــن الهفــوف‬\n      ‫برقــم (‪ )......‬و‪......‬باكســتاني اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n      ‫الدمــام برقــم (‪ )......‬ولــم يحضــر املدعــى عليــه الثانــي ‪......‬اجلنســية‬\n      ‫مبوجــب اإلقامــة رقــم (‪ )......‬وال مــن ميثلــه شــرعا ولــم يبــد عــذرا عــن‬\n      ‫التخلــف كمــا حضــر املترجــم ‪......‬هنــدي اجلنســية مبوجــب اإلقامــة‬\n      ‫الصــادرة مــن الهفــوف برقــم (‪ )......‬وبســؤال املدعــي العــام عــن دعــواه‬\n      ‫قــال بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبحافظــة األحســاء‬\n      ‫أدعــي علــى كل مــن ‪( ،...... -1‬باكســتاني اجلنســية ) مبوجــب رخصــة‬\n\n‫‪315‬‬\n\f‫اإلقامــة رقــم (‪ )......‬البالــغ مــن العمــر (‪21‬عامــا) ‪ ،‬غيــر محصــن ‪،‬‬\n‫أوقــف بتاريــخ ‪1432/9/20‬ه ـ مفــرج عنــه يســكن مبحافظــة ‪-2 .....‬‬\n‫‪( ،......‬باكســتاني اجلنســية ) مبوجــب رخصــة اإلقامــة رقــم (‪ )......‬البالــغ‬\n‫مــن العمــر (‪18‬عامــا) ‪ ،‬غيــر محصــن ‪ ،‬أوقــف بتاريــخ ‪1432/9/20‬ه ـ‬\n‫مفــرج عنــه يســكن مبحافظــة األحســاء ‪( ......-3‬باكســتاني اجلنســية )‬\n‫مبوجــب رخصــة اإلقامــة رقــم (‪ )......‬البالــغ مــن العمــر (‪18‬عامــا) ‪ ،‬غيــر‬\n‫محصــن ‪ ،‬أوقــف بتاريــخ ‪1432/9/20‬ه ـ مفــرج عنــه يســكن مبحافظــة‬\n‫األحســاء ‪( ،...... -4‬باكســتاني اجلنســية ) مبوجــب رخصــة اإلقامــة‬\n‫رقــم (‪ )......‬البالــغ مــن العمــر (‪18‬عامــا) ‪ ،‬غيــر محصــن ‪ ،‬أوقــف بتاريــخ‬\n‫‪1432/9/20‬ه ـ مفــرج عنــه يســكن مبحافظــة األحســاء فإنــه بتاريــخ‬\n‫‪1432/9/20‬ه ـ وأثنــاء قيــام دوريــة األمــن بعملهــا بالقــرب مــن دوار ‪......‬‬\n‫شــاهدت املتهمــن املذكوريــن يجاهــرون بالفطــر يف نهــار رمضــان‬\n‫وبســماع أقــوال األول والثالــث والرابــع ‪ /‬أقــروا مبجاهرتهــم بالفطــر يف‬\n‫نهــار رمضــان ‪ .‬وبســماع أقــوال الثانــي ‪ /‬أنكــر مجاهرتــه بالفطــر يف‬\n                                                                      ‫نهــار رمضــان‪.‬‬\n‫وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام للمذكوريــن باملجاهــرة‬\n                           ‫بالفطــر يف نهــار رمضــان لألدلــة والقرائــن التاليــة‪:‬‬\n‫‪ -1‬أقــوال املذكوريــن املدونــة علــى الصفحــات رقــم (‪ )2-14-13‬مــن‬\n                                  ‫دفتــري االســتدالل املرفقــن لفــة رقــم (‪.)2-1‬‬\n‫‪ -2‬محضــر القبــض املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ )3‬وبالبحــث‬\n                     ‫عمــا إذا كان لهــم ســوابق لــم يعثــر لهــم علــى ســوابق ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــورون وهــم بكامــل أهليتهــم املعتبــرة‬\n‫شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليهــم‬\n\n\n                                                                                        ‫‪316‬‬\n\f      ‫واحلكــم عليهــم بعقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم هــذه دعــواي‬\n      ‫وبســؤال املدعــى عليــه األول ‪......‬عــن دعــوى املدعــي العــام بواســطة‬\n      ‫املترجــم أجــاب قائــا إن مــا ذكــره املدعــي العــام يف دعــواه مــن قيامــي‬\n      ‫باملجاهــرة بالفطــر يف نهــار رمضــان فصحيــح هــذه إجابتــي هــذا فتــم‬\n      ‫ســؤاله هــل أنــت مســلم فقــال نعــم هكــذا قــال وبســؤال املدعــى عليــه‬\n      ‫الثالــث ‪......‬عــن دعــوى املدعــي العــام بواســطة املترجــم أجــاب قائــا إن‬\n      ‫مــا ذكــره املدعــي العــام يف دعــواه مــن قيامــي باملجاهــرة بالفطــر يف‬\n      ‫نهــار رمضــان فصحيــح هــذه إجابتــي هــذا فتــم ســؤاله هــل أنــت مســلم‬\n      ‫فقــال نعــم هكــذا قــال وبســؤال املدعــى عليــه الرابــع ‪......‬عــن دعــوى‬\n      ‫املدعــي العــام بواســطة املترجــم أجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n      ‫يف دعــواه مــن قيامــي باملجاهــرة بالفطــر يف نهــار رمضــان فصحيــح هــذه‬\n      ‫إجابتــي هــذا فتــم ســؤاله عــن ديانتــه فقــال مســلم هكــذا قــال ونظــرا‬\n      ‫لكــون املدعــى عليــه الثانــي ‪......‬لــم يحضــر موعــد هــذه اجللســة لــذا فقــد‬\n      ‫قــررت رفــع اجللســة وإحضــار املدعــى عليــه ‪......‬باخلفــارة يف موعــد اجللســة‬\n      ‫القادمــة ويف جلســة أخــرى وفيهــا حضــر املدعــي العــام وحضــر حلضــوره‬\n      ‫املدعــى عليهــم كمــا حضــر املدعــى عليــه الثانــي ا‪ ......‬باكســتاني‬\n      ‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن الهفــوف برقــم (‪ )......‬وحضــر‬\n      ‫حلضورهــم املترجــم وبســؤال املدعــى عليــه الثانــي ‪......‬بواســطة املترجــم‬\n      ‫أجــاب قائــا إن مــا ذكــره املدعــي العــام مــن قيامــي مبجاهرتــي بالفطــر‬\n      ‫يف نهــار رمضــان فغيــر صحيــح فأنــا كنــت جالس ـ ًا معهــم ولــم أفطــر‬\n      ‫وقمــت باإلنــكار عليهــم هــذه إجابتــي كمــا أضــاف املدعــى عليــه‬\n      ‫األول والثالــث والرابــع كل واحــد منهــم أن املدعــى عليــه الثانــي لــم يقــم‬\n      ‫بالفطــر معنــا بــل نصحنــا ملــا شــاهدنا ونحن نفطر ونحــن تائبون إلى اهلل‬\n\n\n‫‪317‬‬\n\f‫ونادمــون علــى مــا بــدر منــا هكــذا أضافــوا وبطلــب البينــة مــن املدعــي‬\n‫العــام علــى مــا أنكــره املدعــى عليــه الثانــي قــال ليــس لــدي بينــة ســوى‬\n‫مــا ورد يف أوراق املعاملــة هكــذا قــال هــذا فتــم اطالعــي علــى محضــر‬\n‫القبــض املرفــق يف املعاملــة علــى اللفــة رقــم (‪ )3‬ويتضمــن (مشــاهدة‬\n‫رجــال األمــن للمدعــى عليهــم وهــم يقومــون باإلفطــار يف نهــار رمضــان)‬\n‫أ‪.‬هـ ـ وبعرضــه علــى املدعــى عليــه الثانــي قــال غيــر صحيــح فأنــا لــم أقــم‬\n‫بالفطــر مطلقـ ًا فأنــا أخــاف اهلل ســبحانه وتعالــى هكــذا قــال فبناء على‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه األول والثالــث‬\n‫والرابــع بدعــوى املدعــي العــام وأنكــر املدعــي عليــه الثانــي وحيــث ال‬\n‫يوجــد لــدى املدعــي العــام بينــة ســوى مــا ورد يف أوراق املعاملــة ونظــرا‬\n‫لكــون الصيــام مــن أعظــم الفرائــض التــي كتبهــا اهلل ســبحانه علــى‬\n‫عبــاده املوحديــن‪ ،‬ونظــرا لكــون املدعــى عليهــم قــد جمعــوا بــن جرمــن‬\n‫جــرم انتهــاك حرمــة الزمــان وذلــك باإلفطــار يف نهــار رمضــان بــدون‬\n‫عــذر شــرعي وجــرم املجاهــرة باملعصيــة وإن الفطــر يف نهــار رمضــان‬\n‫بــدون عــذر شــرعي فعــل محــرم بــل يعتبــر كبيــرة مــن كبائــر الذنــوب‪-‬‬\n‫ويــزداد حجــم اجلــرم إذا انضــم إلــى فطــره مجاهرتــه بهــذا الفطــر أمــام‬\n‫الصائمــن فاملجاهــرة باإلفطــار‪ ،‬تعــد نوع ـ ًا مــن التبجــح واالفتخــار‬\n‫باملعصيــة‪ ،‬فاملجاهــر ال يســتحي مــن اهلل ‪ -‬جــل وعــا ‪ -‬وال يســتحي‬\n‫مــن النــاس ممــا يــؤدي ذلــك إلــى جــرح مشــاعر الصائمــن‪ ،‬وتشــجيع‬\n‫ضعفــاء النفــوس علــى االقتــداء بــه وقــد ذم النبــي ‪ -‬صلــى اهلل عليــه‬\n‫وســلم ‪ -‬الذيــن جاهــروا مبعاصيهــم وأظهروهــا؛ فقــد قــال‪(( :‬كل أمتــي‬\n‫معافــى إال املجاهريــن)) متفــق عليــه لذلــك كلــه فقــد قــررت مــا يلــي‪:‬‬\n‫أوال‪ :‬ثبــت لــدي قيــام املدعــى عليــه األول والثالــث والرابــع باملجاهــرة‬\n\n\n                                                                                      ‫‪318‬‬\n\f      ‫بالفطــر يف نهــار رمضــان بــدون عــذر شــرعي ونظــرا لكــون املدعــى‬\n      ‫عليهــم ال يوجــد عليهــم ســوابق وأبــدو التوبــة والنــدم لــذا فقــد قــررت‬\n      ‫جلــد كل واحــد منهــم ثالثــن جلــدة علنــا ثانيــا‪ :‬لــم يثبــت لــدي قيــام‬\n      ‫املدعــى عليــه الثانــي باملجاهــرة بالفطــر يف نهــار رمضــان إال أن التهمــة‬\n      ‫تتوجــه نحــوه ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق وملــا‬\n      ‫ذكــره أنــه قــام باإلنــكار علــى املدعــى عليهــم حــن مجاهرتهــم بالفطــر‬\n      ‫ولكــون التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل حســبما نــص عليــه أهــل‬\n      ‫العلــم لــذا فقــد مت توبيــخ املدعــى عليــه وإفهامــه مبغبــة عملــه ثالثــا‪:‬‬\n      ‫أخــذ التعهــد الشــديد علــى املدعــى عليهــم ومبــا ســبق كلــه حكمــت‬\n      ‫وأفهمــت املدعــى عليهــم بــأن عليهــم التوبــة إلــى اهلل وقضــاء هــذا اليــوم‬\n      ‫الــذي أفطــروا فيــه وبعــرض احلكــم علــى املدعــى عليهــم قــرروا القناعــة‬\n      ‫بــه كمــا قــرر املدعــي العــام املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة‬\n      ‫الدعــوى عــن تقــدمي الئحــة اعتراضيــة وبذلــك تكــون القضيــة منتهيــة‬\n      ‫وقــررت بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف بالشــرقية‬\n      ‫لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا‬\n                                  ‫محمــد وعلــى آلــه وصحبــه وســلم تســليما كثيــرا‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/ 34/1913748‬ج‪ 2‬وتاريــخ ‪1434/8/8‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n      ‫برقــم ‪ 341212383‬وتاريــخ ‪1434/8/1‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪...... /‬املســجل برقــم‬\n      ‫‪ 34266487‬وتاريــخ ‪3414/7/12‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام‬\n\n\n‫‪319‬‬\n\f‫ضــد‪/‬كل مــن ‪( ....../4....../3....../2 ....../1‬باكســتانيون اجلنســية)‬\n‫يف قضيــة تــرك الصــوم الواجــب‪ ،‬وقــد تضمــن القــرار حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n‫املعاملــة قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/8/21‬ه ـ‬\n\n\n\n\n                                                                               ‫‪320‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":313,"source_page_end":320,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c1341af19e9f956f378f3ccf6607b6f5b4abe3ae433dd90f77472a1d942d644c","normalized_text_hash":"a59bc80a1c710ab960dbad7a3d394f2bcc35ab722100d5e460306df9ec306392","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p313-34266487"},{"id":"6ec8bb58-fb56-5078-9ed0-e387c7347c78","document_type":"judgment","category":"judicial","subcategory":"general","title":"اإلفطار يف نهار رمضان بغير عذر -مراعاة حرمة الزمان واملكان عند تقدير العقوبة -إثبات اإلدانة باإلقرار -التعزير باجللد - عالنية تنفيذ العقوبة.","document_number":"3415026","case_number":"33602310","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/18","year":"1434","subject":"اإلفطار يف نهار رمضان بغير عذر -مراعاة حرمة الزمان واملكان عند تقدير العقوبة -إثبات اإلدانة باإلقرار -التعزير باجللد - عالنية تنفيذ العقوبة.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 3415026:‬تاريخه‪1434/1/18 :‬هـ رقم‬\n                                ‫الدعوى‪33602310:‬‬\n             ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                     ‫‪ 3423615‬تاريخه‪1434/1/26 :‬هـ‬\n\n\n        ‫اإلفطــار يف نهــار رمضــان بغيــر عــذر ‪ -‬مراعــاة حرمــة الزمــان واملــكان‬\n        ‫عنــد تقديــر العقوبــة ‪ -‬إثبــات اإلدانــة باإلقــرار ‪ -‬التعزيــر باجللــد ‪-‬‬\n                                                          ‫عالنيــة تنفيــذ العقوبــة‪.‬‬\n\n\n\n        ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                            ‫حكمه ‪.‬‬\n\n\n\n        ‫جــرى توجيــه االتهــام للمدعــى عليه بإفطاره يف نهار رمضان عاملا عامدا‬\n        ‫مــن غيــر عــذر وطلــب إيقــاع العقوبــة التعزيريــة عليــه‪ ،‬حيــث قبــض علــى‬\n        ‫املدعــى عليــه مــن قبــل هيئــة األمــر باملعــروف والنهــي عــن املنكــر أثنــاء‬\n        ‫مشــاهدته يف نهــار رمضــان وهــو يقــوم بالتدخــن ‪ -‬أقــر املدعــى عليــه‬\n        ‫بصحــة التهمــة املنســوبة إليــه ودفــع بــأن ســبب فطــره املــرض واإلرهــاق‬\n        ‫مــن العمــل ‪ -‬جــرى ســؤاله عــن التقريــر الطبــي للمــرض فقــرر أنــه ليــس‬\n        ‫لديــه تقريــر طبــي ‪ -‬بنــاء علــى إقــرار املدعــى عليــه وألن التعزيــر مشــروع‬\n        ‫يف كل معصيــة ال حـ ّـد فيهــا وال كفــارة وهــو يختلــف باختالف األحوال‬\n        ‫وتقديــره راجــع لنظــر احلاكــم‪ ،‬فقــد حكمــت احملكمــة بجلــده تســع‬\n        ‫وســبعني جلــدة دفعــة واحــدة ويف محــل عــام وأخــذ التعهــد عليــه بعــدم‬\n        ‫العــودة ‪ -‬قــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام وطلــب‬\n‫‪321‬‬\n\f‫رفــع القضيــة لالســتئناف بــدون الئحــة‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                        ‫االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باملدينة املنورة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫اجلزائيــة باملدينــة املنــورة برقــم ‪ 33602310‬وتاريــخ ‪ 1433/10/15‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 331808125‬وتاريــخ ‪ 1433/10/15‬ه ـ ففــي‬\n‫يــوم األحــد املوافــق‪ 1433/11/14‬ه ـ افتتحــت اجللســة الســاعة ‪09 : 00‬‬\n‫وفيهــا قــدم املدعــي ‪........... /‬ضــد احلاضــر باملجلــس الشــرعي املدعــو ‪/‬‬\n‫‪...........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ( ‪ . )...........‬حيــث‬\n‫أنــه باالطــاع علــى محضــر القبــض املعــد مــن قبــل هيئــة األمــر باملعــروف‬\n‫والنهــي عــن املنكــر بتاريــخ ‪1433/09/09‬ه ـ املتضمــن مشــاهدة‬\n‫املذكــور أعــاه وهــو يقــوم بالتدخــن يف نهــار رمضــان فتــم القبــض‬\n‫عليــه وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باإلفطــار يف‬\n‫نهــار رمضــان وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف اعترافــه‬\n‫املنــوه عنــه املــدون بالتفصيــل علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق‬\n‫لفــه رقــم (‪ -2 . )1‬محضــر القبــض املــدون علــى الصفحــة رقــم (‪. )2‬‬\n‫وحيــث أن مــا أقــدم عليــه املتهــم املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء‬\n‫ذلــك ‪ .‬ويف يــوم االثنــن املوافــق ‪ 1434/0/12‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫ا نعــم صحيــح مــا ذكــره‬       ‫حضــر املدعــى عليــه وبســؤاله أجــاب قائ ـ ً‬\n‫املدعــي العــام يف دعــواه حيــث أننــي بتاريــخ ‪1433/09/09‬ه ـ قبــض علي‬\n\n                                                                                       ‫‪322‬‬\n\f      ‫مــن قبــل الهيئــة وأنــا أدخــن يف نهــار رمضــان بســبب أننــي مرهــق مــن‬\n      ‫العمــل ومريــض فأفطــرت هــذه إجابتــي فســألت املدعــى عليــه هــل لديــك‬\n      ‫ا ال ليــس لــدي تقريــر ولكــن اســتأذنت‬     ‫تقريــر طبــي ملرضــك قــرر قائ ـ ً‬\n      ‫مــن العمــل للخــروج بســبب اإلرهــاق والتعــب هــذا ماحصــل منــي فبنــاء‬\n      ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وإلقــرار املدعــى عليــه بدعــوى‬\n      ‫املدعــي العــام وحيــث لــم ُيثبــت املدعــى عليــه مرضــه بــل وأقــر أنــه يف‬\n      ‫ـدي قيــام‬\n               ‫دوام وعمــل وإلفطــاره علــى محــرم وخبيــث لــذا فقــد ثبــت لـ ّ‬\n      ‫املدعــى عليــه ‪ ...........‬باإلفطــار يف نهــار رمضــان بــدون عــذر شــرعي‬\n      ‫علــى محــرم وحكمــت عليــه لقــاء ذلــك بجلــده تســع وســبعني جلــده‬\n      ‫دفعــة واحــده يف محفــل عــام وبعــد ذلــك يؤخــذ عليــه التعهــد بعــدم العــودة‬\n      ‫ال وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬       ‫ملثــل ذلــك مســتقب ً‬\n      ‫القناعــة باحلكــم وقــرر املدعــي العــام االعتــراض بــدون الئحــة وعليــه‬\n      ‫جــرى أثباتــه وصلــى اهلل علــى ســيدنا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعد ‪ -:‬فقد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة األولــى يف محكمــة االســتئناف‬\n      ‫مبنطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة الينــا مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪332110717‬‬\n      ‫وتاريــخ ‪ 1434/1/20‬ه ـ املرفــق بــه االقــرار الشــرعي رقــم ‪3415026‬‬\n      ‫وتاريــخ ‪ 1434/1/18‬ه ـ الصــادر مــن فضيلــة الشــيخ ‪........... /‬القاضــي‬\n      ‫يف احملكمــة اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن دعــوى املدعــي العــام‬\n      ‫ضــد ‪ ........... /‬املتهــم بقضيــة تــرك الصــوم الواجــب أو اإلفطــار بنهــار‬\n                   ‫رمضــان بــدون عــذر شــرعي احملكــوم فيــه مبــا دون باطنــه‪.‬‬\n      ‫وبدراســة احلكــم وصــورة ضبطــه قررنــا املوافقــة علــى احلكــم واهلل‬\n          ‫املوفــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫‪323‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":321,"source_page_end":323,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"91f2295769cacc0b6909d512d7d99adb2843b507b24bb36414a0e90374715dbb","normalized_text_hash":"e0dee1e26c71e0318b28e4c0db83b89b7ad5899c6ea93f26be9e289303d791bb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p321-3415026"},{"id":"e6bc3ac2-8cd6-597b-a20b-255a09d2d188","document_type":"judgment","category":"judicial","subcategory":"general","title":"اإلفطار يف نهار رمضان -الهروب من الدورية األمنية -مشروعية التعزير للشبهة إذا قويت -رد دعوى (صرف نظر ) عن اإلدانة - التعزير بالسجن للشبهة يف اإلفطار بنهار رمضان -العبرة بشهادة رجل األمن أمام المحكمة وإن خالفت إفادته يف دفتر التحقيق .","document_number":"34374435","case_number":"34440661","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/1","year":"1434","subject":"اإلفطار يف نهار رمضان -الهروب من الدورية األمنية -مشروعية التعزير للشبهة إذا قويت -رد دعوى (صرف نظر ) عن اإلدانة - التعزير بالسجن للشبهة يف اإلفطار بنهار رمضان -العبرة بشهادة رجل األمن أمام المحكمة وإن خالفت إفادته يف دفتر التحقيق .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34374435 :‬تاريخه‪1434/12/1 :‬ه‬\n                   ‫رقم الدعوى‪34440661:‬‬\n   ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35107877‬تاريخه‪1434/1/8 :‬هـ‬\n\n\n‫اإلفطــار يف نهــار رمضــان ‪ -‬الهــروب مــن الدوريــة األمنيــة ‪ -‬مشــروعية‬\n‫التعزيــر للشــبهة إذا قويــت ‪ -‬رد دعــوى (صــرف نظــر ) عــن اإلدانــة ‪-‬‬\n‫التعزيــر بالســجن للشــبهة يف اإلفطــار بنهــار رمضــان ‪ -‬العبــرة بشــهادة‬\n   ‫رجــل األمــن أمــام احملكمــة وإن خالفــت إفادتــه يف دفتــر التحقيــق ‪.‬‬\n\n\n\n‫‪ -1‬مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف‬\n                                                           ‫تســبيب احلكــم‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام علــى املدعــى عليــه بهروبــه مــن الدوريــة األمنيــة بعــد‬\n‫مشــاهدته لهــا‪ ،‬وقيامــه بصدمهــا عمــدا أثنــاء محاولتــه للهــرب منهــا‪،‬‬\n‫ممــا أدى لتضــرر ســيارة الدوريــة بكســر الشــبك األمامــي وكســر‬\n‫الصــدام األمامــي‪ ،‬وإفطــاره يف نهــار رمضــان‪ ،‬حيــث شــوهد بيــده‬\n‫ســيجارة ملــا ترجــل مــن ســيارته‪ ،‬ويطلــب إثبــات مــا أســند إليــه وإيقــاع‬\n‫العقوبــة التعزيريــة عليــه وتشــديدها كونــه ميــس هيبــة الدولــة ‪ -‬أنكــر‬\n‫املدعــى عليــه التهمــة ‪ -‬استشــهد املدعــي العــام مبحضــر تنفيــذ املهمــة‬\n‫وإفــادة رجــل األمــن يف دفتــر التحقيــق وهمــا موافقــان ملــا ورد يف الئحــة‬\n‫االدعــاء ‪ -‬أنكــر املدعــى عليــه مــا تضمنــه احملضر وإفــادة رجل األمن ‪-‬‬\n\n                                                                                        ‫‪324‬‬\n\f      ‫حضــر أحــد رجــال الفرقــة القابضــة وشــهد بشــهادة نافيــة كــون املدعــى‬\n      ‫عليــه تعمــد صــدم الدوريــة وأنــه ال يعلــم أنــه كان املدعــى عليــه هــرب‬\n      ‫مــن الدوريــة أم ال‪ ،‬ألن املدعــى عليــه كان مســرع ًا وأن الدوريــة هــي مــن‬\n      ‫صدمــت املدعــى عليــه وأن املدعــى عليــه نــزل مــن الدوريــة ومعــه ســيجارة‬\n      ‫‪ -‬صــدر احلكــم بــرد الدعــوى بشــأن طلــب إثبــات اإلدانــة‪ ،‬كمــا مت‬\n      ‫توجيــه التهمــة للمدعــى عليــه باإلفطــار يف نهــار رمضــان وصــدور احلكم‬\n              ‫بســجن املدعــى عليــه وصــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ...........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة القطيــف وبنــاء علــى املعاملــة احملالــة مــن فضيلــة الرئيــس‬\n      ‫برقــم ‪ 34440661‬وتاريــخ ‪1434/10/8‬ه ـ املقيــدة باحملكمــة برقــم‬\n      ‫‪ 342270386‬وتاريــخ ‪1434/10/8‬ه ـ واملتعلقــة بدعــوى املدعــي العــام‬\n      ‫‪...................... /‬ضــد ‪ ........... /‬ســعودي اجلنســية حســب بطاقــة الهويــة‬\n      ‫الوطنيــة رقــم (‪ )...........‬ففــي يــوم األحــد ‪1434/ 10 / 18‬ه ـ فتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 30‬وفيهــا حضــر املدعــي العــام واملدعــى عليــه‬\n      ‫املدونــة هويتــه بعاليــه وقــدم املدعــي العــام الئحــة الدعــوى املتضمنــة‬\n      ‫مايلــي‪ :‬بصفتــي عضــو هيئــة التحقيــق واإلدعاء العام مبحافظة القطيف‬\n      ‫أدعــي علــى ‪ ........... :‬البالــغ مــن العمــر (‪ )25‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪ )...........‬أعــزب ‪ ،‬موظــف أهلــي ‪ ،‬يقيــم‬\n      ‫مبحافظــة القطيــف املقبــوض عليــه بتاريــخ ‪1434/9/12‬ه ـ ‪ ،‬وأحيــل‬\n      ‫إلــى ســجن القطيــف بتاريــخ ‪1434/9/22‬ه ـ اســتناد ًا للقــرار الــوزاري‬\n      ‫رقــم (‪ )1900‬وتاريــخ ‪1428/7/9‬ه ـ ‪ .‬حيــث إنــه بتاريــخ ‪1434/9/12‬ه ـ‬\n\n‫‪325‬‬\n\f‫‪ ،‬لوحــظ املذكــور مــن قبــل الدوريــات األمنيــة وحــن مشــاهدته‬\n‫للدوريــة الذ بالفــرار وبعــد خمــس دقائــق تقريبــا متــت مشــاهدته يف موقــع‬\n‫آخــر وعنــد محاولتــه الهــروب قــام بصــدم الدوريــة مــن اجلهــة األماميــة‬\n‫وعنــد نــزول الشــخص مــن ســيارته لوحــظ يف يــده ســيجاره وأنــه مفطــر‬\n‫يف نهــار رمضــان فتــم القبــض عليــه ‪ ،‬وقــد تضــررت الدوريــة األمنيــة‬\n‫بكســر يف الشــبك األمامــي وكذلــك كســر يف الصــدام األمامــي ‪،‬‬\n‫ووردنــا خطــاب قائــد دوريــات األمــن مبحافظــة القطيــف يفيــد بأنهــم ال‬\n‫يطالبــون املذكــور بإصــاح الدوريــة األمنيــة حيــث إنــه مت إصالحهــا‬\n‫علــى املذكــور ‪ .‬وبســماع أقوالــه واســتجوابه أقــر بعائديــة الســيارة لــه‬\n‫وأنــه كان يقودهــا ‪ .‬وقــد انتهــى التحقيــق معــه إلــى توجيــه االتهــام‬\n‫إليــه بالهــروب مــن الدوريــة األمنيــة ‪ ،‬وصدمهــا عمــد ًا واإلفطــار يف‬\n‫نهــار رمضــان ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬إقــراره يف دفتــر‬\n‫التحقيــق املنــوه عنــه املرفــق صفحــة (‪ )2‬لفــة رقــم ( ‪ -2 .) 12‬محضــر‬\n‫تنفيــذ مهمــة وتســليمه اجلهــة االختصــاص املرفــق علــى اللفــة رقــم (‪.)2‬‬\n‫‪ -3‬محضــر معاينــة حــادث املرفــق علــى اللفــة رقــم ( ‪ ( . 3‬وبالبحــث عــن‬\n‫ســوابقه علــى مســتوى القطيــف لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n‫شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا اســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة مــع التشــديد عليــه وفــق تعميــم وزيــر‬\n‫الداخليــة رقــم ‪ 33522‬وتاريــخ ‪1428 / 5 /17-16‬ه ـ لكــون مــا أســند‬\n‫إلــى املذكــور ميــس هيبــة الدولــة‪ .‬وبــاهلل التوفيــق ا‪ .‬ه ـ ‪ .‬وبعــرض الدعــوى‬\n‫علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف الدعــوى كلــه غيــر صحيــح‬\n‫هــذا جوابــي وبعــرض ذلــك علــى املدعــي العــام قــال الصحيــح مــا جــاء‬\n\n\n                                                                                       ‫‪326‬‬\n\f      ‫يف دعــواي وبســؤاله البينــة قــال بينتــي ذكرتهــا يف الدعــوى وأطلــب‬\n      ‫رصدهــا هــذا جوابــي وباالطــاع علــى أدلــة املدعــي العــام وجــدت علــى‬\n      ‫اللفــة رقــم ‪ 2‬محضــر تنفيــذ مهمــة يتضمــن مــا نصــه ‪ ( :‬أثنــاء مــرور‬\n      ‫الدوريــة ‪...........‬مــن شــارع ‪ ...........‬لوحــظ الشــخص املذكــور بياناتــه‬\n      ‫يف األعلــى وعنــد مالحظتــه للدوريــة الذ بالفــرار وبعدهــا بخمــس دقائــق‬\n      ‫لوحــظ الشــخص يف موقــع آخــر وقــام بصــدم الدوريــة وعنــد نزولــه مــن‬\n      ‫املركبــة لوحــظ الشــخص بيــده زقــارة (مفطــر) مالحظــة أثنــاء قيامــه‬\n      ‫مبحاولــة الهــروب ثــم اصطدامــه بالدورية ‪ ).‬ا‪.‬ه ـ كما وجدت على اللفة‬\n      ‫رقــم ‪ 3‬تقريــر حــادث مــروري أولــي ويتضمــن مــا نصــه ‪ ( :‬ملخــص احلــادث‬\n      ‫‪ :‬حــادث طرفــن اختــاف أقــوال بــن الطرفــن علم ـ ًا الطــرف الثانــي‬\n      ‫دوريــة رســمية (دوريــة أمنيــة) ا‪.‬ه ـ كمــا وجــدت علــى الصفحــات رقــم‬\n      ‫‪ 12-9‬مــن دفتــر التحقيــق رقــم ‪ 1‬إفــادة العســكري ‪ ...........‬ويتضمــن مــا‬\n      ‫ورد يف الئحــة الدعــوى وبعــرض األدلــة علــى املدعــى عليــه قــال مــا ورد‬\n      ‫يف األدلــة غيــر صحيــح هــذا جوابــي وبســؤال املدعــي العــام زيــادة بينــة‬\n      ‫وعــد بإحضــار الفرقــة القابضــة ويف جلســة أخــرى حضــر املدعــي العــام‬\n      ‫واملدعــى عليــه ولــم يحضــر شــهود القبــض وطلــب املدعــي العــام مهلــة‬\n      ‫أخــرى إلحضارهــم فأجبتــه لطلبــه وأفهمتــه بأنهــا املهلــة األخيــرة ويف‬\n      ‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه وأحضــر املدعــي العــام‬\n      ‫للشــهادة ‪ ........... /‬ســعودي اجلنســية حســب بطاقــة الهويــة الوطنيــة رقــم‬\n      ‫‪ ...........‬وبســؤاله قــال إنــي أعمــل يف الدوريــات األمنيــة بالقطيــف برتبــة‬\n      ‫جنــدي أول وأشــهد بأنــه يف نهــار رمضــان شــاهدنا املدعــى عليــه مســرعا‬\n      ‫بســيارته وهــي مظللــة بالكامــل بتظليــل قــامت فلحقنــا بــه فغــاب عــن‬\n      ‫أنظارنــا وبالبحــث عنــه يف نفــس احلــي شــاهدناه أخــذ أحــد املنعطفــات‬\n\n\n‫‪327‬‬\n\f‫شــبه مســرع واجتــه لنــا فقمــت بحــرف ســيارة الدوريــة عليــه وأنــا أســير‬\n‫بســرعة بطيئــة فصدمنــا مبقدمــة ســيارته ثــم نــزل ومعــه ســيجارة هــذه‬\n‫شــهادتي فســألت الشــاهد ‪ :‬هــل هــرب منكــم يف املــرة األولــى؟ فأجــاب‬\n‫بقولــه ‪ :‬ال أدري هــل شــاهدنا وهــرب أم ال ألنــه كان مســرعا هــذا‬\n‫جوابــي وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال ‪ :‬الشــاهد‬\n‫ال أعرفــه وأمــا شــهادته فإنــي لــم أهــرب وهوالــذي انحــرف علـ ّـي بســيارة‬\n‫الدوريــة وأمــا الســيجارة التــي شــاهدها معــي فإنــه بعــد احلــادث تبعثــرت‬\n‫أغراضــي داخــل الســيارة ومــن ضمنهــا ســيجارة مدخنــة ليــا وبعــد‬\n‫نزولــي قمــت برمــي الســيجارة خــارج الســيارة فظنــوا أنــي كنــت أدخــن‬\n‫يف نهــار رمضــان هــذا جوابــي ورفعــت اجللســة للتأمــل والدراســة ويف‬\n‫جلســة أخــرى حضــر املدعــي العــام واملدعــى عليــه فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وحيــث أنكراملدعــى عليــه الدعــوى وألن شــهادة‬\n‫الشــاهد وهــو أحــد معــدي محضــر القبــض يظهــر منهــا عــدم هــروب‬\n‫املدعــى عليــه وأنــه لــم يقــم بصــدم الدوريــة وإمنــا ســائق الدوريــة هــو الــذي‬\n‫انحــرف عليــه واصطــدم بــه‪ ،‬وحيــث أقــر املدعــى عليــه بأنــه كان‬\n‫يف يــده ســيجارة ألقاهــا عنــد القبــض عليــه وهــذه قرينــة علــى تعاطيــه‬\n‫لهــا يف نهــار رمضــان فقــد حكمــت مبــا يلــي ‪ -1 :‬رد دعــوى املدعــي‬\n‫العــام بشــأن طلبــه إثبــات إدانــة املدعــى عليــه بالهــروب مــن الدوريــة‬\n‫األمنيــة ‪ ،‬وصدمهــا عمــد ًا واإلفطــار يف نهــار رمضــان؛ مــع توجــه التهمــة‬\n‫عليــه باإلفطــار يف نهــار رمضــان ‪ -2 .‬معاقبتــه للشــبهة بســجنه مــدة‬\n‫ثالثــة أيــام حتتســب منهــا مــدة إيقافــه الســابقة وبعــرض احلكــم علــى‬\n‫الطرفــن قرراملدعــي العــام عــدم قناعتــه ورغبتــه رفــع احلكــم حملكمــة‬\n‫االســتئناف بــدون الئحــة اعتراضيــة وقــرر املدعــى عليــه قناعتــه وبــاهلل‬\n\n\n                                                                                          ‫‪328‬‬\n\f      ‫التوفيــق وقــد مت االنتهــاء مــن حتريــره يف متــام الســاعة ‪،،، 10 : 00‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء ‪1435/1/24‬ه ـ فتحــت اجللســة‬\n      ‫الســاعة ‪ 11 : 00‬وقــد وردتنــا املعاملــة وبرفقهــا قــرار أصحــاب الفضيلــة‬\n      ‫قضــاة محكمــة االســتئناف باملنطقــة الشــرقية رقــم ‪ 35107877‬يف‬\n      ‫‪1435/1/8‬ه ـ املتضمــن املصادقــة علــى احلكــم وبــاهلل التوفيــق وقــد مت‬\n                                     ‫االنتهــاء مــن حتريــره يف متــام الســاعة ‪.11 : 10‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n      ‫لــدى احملكمــة برقــم ‪/34/2807196‬ج‪ 2‬وتاريــخ ‪1434/12/18‬ه ـ‬\n      ‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة القطيــف‬\n      ‫املكلــف برقــم ‪ 342270386‬وتاريــخ ‪1434/12/3‬ه ـ املرفــق بهــا القــرار‬\n      ‫الصادرمــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ........... /‬املســجل برقــم‬\n      ‫اخلــاص بدعــوى ‪ /‬املدعــي‬                  ‫‪ 34374435‬وتاريــخ ‪1434/12/1‬ه ـ‬\n      ‫العــام ضــد ‪....................../‬يف قضيــة هــروب مــن رجــال األمــن وقــد‬\n      ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم ‪.‬‬\n      ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرريف‬\n                                                                           ‫‪1435/1/7‬هــ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f330\n\f331\n\f332\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":324,"source_page_end":332,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"089e07eca2070f4c454f5fb99aa7860dbf4baef50c245d5da3dd501b9482e754","normalized_text_hash":"493a8588b17eb1ca5ad54c6ce545e758948fe8eb2ea2a6b0db788a6a60879afc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p324-34374435"},{"id":"eb27f53f-03e4-5889-9629-dab5c3916377","document_type":"judgment","category":"judicial","subcategory":"general","title":"انتحال شخصية محامي -ممارسة مهنه احملاماة من غير ترخيص -الكذب يف الدعاية التجارية -التعزير لقاء انتحال صفة احملامي والترافع بالقضايا.","document_number":"34244363","case_number":"3480222","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة املساعد باخلبر بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/18","year":"1434","subject":"انتحال شخصية محامي -ممارسة مهنه احملاماة من غير ترخيص -الكذب يف الدعاية التجارية -التعزير لقاء انتحال صفة احملامي والترافع بالقضايا.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34244363 :‬تاريخه‪1434/6/18 :‬هـ‬\n                           ‫رقم الدعوى‪3480222:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34291163‬تاريخه‪1434/8/8:‬هـ‬\n\n\n      ‫انتحــال شــخصية محامــي ‪ -‬ممارســة مهنــه احملامــاة مــن غير ترخيص‬\n      ‫‪ -‬الكــذب يف الدعايــة التجاريــة ‪ -‬التعزيــر لقــاء انتحــال صفــة احملامــي‬\n                                                             ‫والترافــع بالقضايا‪.‬‬\n\n\n\n\n      ‫املــادة الســابعة والثالثــن مــن نظــام احملامــاة والفقــرة األولــى مــن لوائح‬\n                                                                             ‫النظام‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام علــى املدعــى عليــه بقيامــه‬\n      ‫بانتحــال شــخصية محامــي بــدون أن يرخــص لــه مــن اجلهــة املختصــة‬\n      ‫وطلــب إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة عليــه ‪ -‬أقــر‬\n      ‫املدعــى عليــه بقيامــه بالترافــع يف قضيــة ماليــة وأنــه ال يحمــل ترخيــص‬\n      ‫محامــاة إال أنــه أنكــر قيامــه بانتحــال شــخصية محامــي ودفــع بأنــه‬\n      ‫مجــرد وكيــل وأن الدعــوى كيديــة مــن املبلــغ ‪-‬خصــم موكلــه يف‬\n      ‫الدعــوى املاليــة ‪ -‬بطلــب البينــة مــن املدعــي العــام قــرر بأنــه بينتــه بطاقــة‬\n      ‫تعريــف باملدعــى عليــه وصفتــه بأنــه محامــي ‪ -‬بعــرض البطاقــة علــى‬\n      ‫املدعــى عليــه أعتــرف بأنــه تعــود لــه ودفــع بأنــه طبعهــا يف دولــة مجــاورة‬\n      ‫بثالثمئــة ريــال وكتــب عليهــا هــذا الوصــف بــدون إذنــه فرجــع لــه وطلــب‬\n\n‫‪333‬‬\n\f‫منــه تغييرهــا فاعتــذر بــأن ذلــك ســيكلفه واقتــرح وضــع الصــق علــى‬\n‫العبــارة فوافــق تقديــرا لظروفــه ولــم يعطــه إال مئــة وخمســن ريــاال ‪-‬‬\n‫بنــاء علــى دعــوى املدعــي العــام وإلقــرار املدعــى عليــه بإصــداره بطاقــة‬\n‫حتــوي لقــب محامــي مقترنــة باســمه الصريــح ‪ ،‬ولعــدم قبــول مــا دفــع بــه‬\n‫مــن حصــول خطــأ مطبعــي حيــث كان باإلمــكان إتالفهــا خصوصــا‬\n‫وأن أجــرة إصدارهــا لــم يكــن كبيــرا ‪ ،‬وألن مــا صــدر عــن املدعــى‬\n‫عليــه محــرم شــرعا ومخالــف للنظــام يســتحق معــه التعزيــر وفقــا للمــادة‬\n‫الســابعة والثالثــن مــن نظــام احملامــاة ‪ ،‬وألجــل مــا تقــدم فقــد قــررت‬\n‫احملكمــة ثبــوت إدانــة املدعــى عليــه بانتحــال صفــة محامــي والترافــع‬\n‫بالقضايــا بصفــة احملامــاة وتعزيــره ألجــل ذلــك بســجنه شــهرين حتتســب‬\n‫منهــا املــدة التــي أوقــف فيهــا علــى ذمــة القضيــة ‪ -‬اعتــرض املدعــي العــام‬\n‫بــا الئحــة واملدعــى عليــه بالئحــة وأفهــم بتعليمــات االســتئناف ‪ -‬صــدق‬\n                                          ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد‬\n‫ـاء علــى‬\n      ‫ـدي أنــا ‪...........‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬     ‫فلـ َّ‬\n‫املعاملــة الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫األحســاء برقــم وتاريــخ ‪1434/02/18‬ه ـ واملقيــدة بهــذه احملكمــة‬\n‫برقــم ‪ ......‬وتاريــخ ‪1434/02/18‬ه ـ واحملالــة إلينــا مــن فضيلــة الرئيــس‬\n‫برقم‪3480222‬وتاريــخ ‪1434/02/18‬ه ـ فتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي العــام ‪...........‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا مبوجــب‬\n‫خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعاء العام مبحافظة األحســاء‬\n\n                                                                                        ‫‪334‬‬\n\f      ‫ا‪:‬‬  ‫ذي الرقــم ‪...........‬والتاريــخ ‪1433/12/01‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n      ‫بصفتــي مدعيـ ًا عامـ ًا يف دائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي‬\n      ‫علــى‪ ،...................... /‬البالــغ مــن العمــر( ) عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم …… ‪ ،‬أوقــف بتاريــخ ‪1433/7/7‬ه ـ‬\n      ‫وأفــرج عنــه بالكفالــة ‪ ،‬يســكن محافظــة األحســاء‪/‬قرية ‪............‬‬\n      ‫إنــه بتاريــخ ‪1433/7/7‬ه ـ ورد لشــرطة محافظــة اخلبــر خطــاب فضيلــة‬\n      ‫رئيــس احملكمــة العامــة املســاعد باخلبــر بنــاء علــى االســتدعاء املقــدم‬\n      ‫مــن املواطــن‪........... /‬اتهامــه للمواطــن‪(........... /‬املدعــى عليــه) بانتحــال‬\n      ‫صفــة محامــي بــدون ترخيــص مــن اجلهــة املختصــة‪ .‬وبضبــط إفــادة املبلــغ‬\n      ‫املدعــو‪...................... /‬ســعودي وأفــاد بــأن هنــاك دعــوى ماليــة بينــه وبني‬\n      ‫املدعــو‪........... /‬فلســطيني اجلنســية ووكيلــه املدعــى عليــه ‪ ،‬وقــد قــام‬\n      ‫املدعــى عليــه باملماطلــة باحلضــور لــدى احملكمــة متعمــد تعطيــل ســير‬\n      ‫القضيــة وقــد كان وكيــل املذكــور ‪...........‬يقــدم احتجاجــات باطلــة‬\n      ‫مدعي ـ ًا بأنــه محامــي وهــو خــاف ذلــك وقــد قــدم لــه كــرت محامــاة‬\n      ‫كاتــب بــه اســمه‪ .‬وباســتجواب املدعــى عليــه‪ :‬أفــاد بأنــه قد قــام بإصدار‬\n      ‫كــروت محامــاة مــن مكتــب طبــع بدولــة ســوريا‪ .‬وقــد أســفر التحقيــق‬\n      ‫معــه عــن توجيــه االتهــام لــه بانتحــال صفــة محامــي والترافــع بالقضايــا‬\n      ‫بصفــة احملامــاة وال يوجــد لديــه ترخيــص ملزاولــة هــذه املهنــة ‪ ،‬وذلــك‬\n                                                         ‫لألدلــة والقرائــن التاليــة‪-:‬‬\n      ‫‪ -1‬اعترافــه حتقيقـ ًا بقيامــه بإصــدار كــروت احملامــاة مــن دولــة ســوريا‬\n      ‫املــدون علــى الصفحــة رقــم (‪ )4 ، 3‬مــن ملــف التحقيــق املرفــق لفــة (‪.)21‬‬\n      ‫ا‬‫‪ -2‬قيــام املذكــور بإصــدار كــروت احملامــاة مــن دولــة ســوريا دلي ـ ً‬\n      ‫علــى قيامــه بانتحــال صفــة احملامــاة كــون ليــس لديه ترخيــص احملاماة‪.‬‬\n\n\n‫‪335‬‬\n\f‫وبالبحــث عمــا إذا كان لــه ســوابق‪ :‬لــم يعثــر لــه علــى ســوابق جنائيــة‬\n‫مســجلة‪ .‬وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو بكامــل أهليتــه‬\n‫املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بعقوبــة وفــق الوجــه الشــرعي هكــذا ا َّدعــى ؛‬\n‫عليــه فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض‬\n‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن‬ ‫دعــوى املدعــي العــام عليــه فأجــاب قائـ ً‬\n‫اتهامــي بانتحــال صفــة محامــي والترافــع بالقضايــا بصفــة احملامــاة غيــر‬\n‫صحيــح والصحيــح أننــي ترافعــت عــن أحــد األشــخاص وقــام املدعــي‬\n‫ملَّــا صــرف النظــر عــن دعــواه برفــع هــذه الدعــوى الكيديــة محــاو ًال‬\n‫الضغــط علــي ملكاملــة موكلــي لدفــع بعــض املبالــغ لــي وصحيــح أنــه‬\n‫ال يوجــد لــدي ترخيــص ملزاولــة احملامــاة وأنــا وكيــل شــرعي هكــذا‬\n‫ـدي ســوى‬ ‫أجــاب وبســؤال املدعــي العــام البينــة علــى دعــواه قــال‪ :‬ليــس لـ َّ‬\n‫مــا يف أوراق املعاملــة وأطلــب الرجــوع إليهــا هكــذا أجــاب ثــم جــرى‬\n‫االطــاع علــى جميــع أوراق املعاملــة ومنهــا ‪ :‬صــورة لكــرت مــدون عليــه‬\n‫اســم املدعــى عليــه مقترنــا باســم محامــي وبعرضــه علــى املدعــى عليــه‬\n‫قــال‪ :‬صحيــح أننــي أصــدرت هــذا الكــرت مــن مطبعــة يف ســوريا مببلــغ‬\n‫ثالثمائــة ريــال وكتــب عليهــا وصــف احملامي دون إذنٍ منــي ورجعت إليه‬\n‫وأن ذلــك ســيكلفه‬     ‫وطلبــت منــه تغييرهــا فتعــذر لــي بأ َّنــه ال يســتطيع َّ‬\n‫واقتــرح علـ َّـي أن يقــوم بوضــع لزقــة عليهــا فوافقــت علــى ذلــك تقديــر ًا‬\n‫لظروفــه ولــم أعطــه إال مائــة وخمســن ريــا ًال هكــذا أجــاب ثــم جــرى‬\n‫االطــاع علــى كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود ســوابق‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال‬    ‫عليــه فبنـ ً‬\n‫أن املدعــى عليــه أقـ َّـر بإصــدار‬\n                                   ‫املدعــى عليــه والتأكــد مــن أهليتــه ومبــا َّ‬\n\n                                                                                          ‫‪336‬‬\n\f      ‫ـأن ذلــك وضــع خطــأ‬    ‫كــرت يحــوي لقــب محامــي مقترنـ ًا باســمه ودفــع بـ َّ‬\n      ‫أن ذلــك الدفــع غيــر مقبــول إذ باإلمــكان إتــاف هــذه‬           ‫مــن الطابــع ومبــا َّ‬\n      ‫وأمــا دعــوى عــدم إرادة إيقــاع‬   ‫وأن املبلــغ ليــس بكبيــر َّ‬ ‫الكميــة الســيما َّ‬\n      ‫صاحــب املطبعــة يف خســارة فقــد أوقعــه فيهــا بعــدم إعطائــه لنصــف‬\n      ‫أن مــا صــدر مــن املدعــى عليــه‬     ‫املبلــغ املتفــق عليــه كمــا ذكــر ومبــا َّ‬\n      ‫مــن احملــرم شــرع ًا واملجــرم نظام ـ ًا إذ يف انتحــال صفــة احملامــي أكل‬\n      ‫ألمــوال النــاس بالباطــل ممــا يســتوجب تعزيــر املدعــى عليــه واســتحقاقه‬\n      ‫للعقوبــة الــواردة يف املــادة الســابعة والثالثــن مــن نظــام احملامــاة لــذا‬\n              ‫كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليــه مبــا يلــي ‪:‬‬\n      ‫ـدي إدانــة املدعــى عليــه بانتحــال صفــة محامــي والترافــع‬            ‫أوالً‪ /‬ثبــت لـ َّ‬\n                                                              ‫بالقضايــا بصفــة احملامــاة ‪.‬‬\n      ‫ثاني ـ ًا ‪ /‬يعــزر ألجــل ذلــك بســجنه ملــدة شــهرين حتتســب منهــا املــدة‬\n      ‫التــي أوقــف فيهــا علــى ذمــة القضيــة وذلــك اســتناد ًا إلــى املــادة الســابعة‬\n      ‫والثالثــن مــن نظــام احملامــاة ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام‬\n      ‫املدعــى عليــه بحقــه يف متييــز احلكــم قرر عــدم قناعته به وطلب متكينه‬\n      ‫مت تســليمه نســخة‬   ‫مــن تقــدمي الئحـ ٍة اعتراضيــة عليــه فأجيــب إلــى طلبــه و َّ‬\n      ‫ـأن مــدة االعتــراض ثالثــون يومـ ًا تبــدأ مــن هذا‬   ‫مــن احلكــم حــا ًال وأفهــم بـ َّ‬\n      ‫اليــوم وإذا لــم يقــدم اعتراضــه خاللهــا فــإن حقــه يف االعتــراض يســقط‬\n      ‫وســوف يرفــع احلكــم حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة‬\n      ‫اعتراضيــة فأبــدى فهمــه لذلــك وطلــب املدعــي العــام رفــع كامــل أوراق‬\n      ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم دون الئحــة اعتراضيــة‬\n      ‫مكتفيـ ًا مبــا ورد يف أوراق املعاملــة وصلــى اهلل وسـلَّم علــى نبينــا محمــد‬\n                             ‫وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/06/18‬ه ـ‬\n\n\n‫‪337‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫يــوم االربعــاء ‪1434/07/19‬ه ـ فتحــت اجللســة الثالثــة الســاعة الثامنــة‬\n‫ـاء علــى الالئحــة املقدمــة ‪...........‬وقــد قيــدت هــذه الالئحــة‬\n                                                                    ‫والنصــف وبنـ ً‬\n‫باحملكمــة برقــم ‪ 34/1744551‬بتاريــخ ‪1434/07/18‬ه ـ واملكونــة‬\n‫مــن صفحتــن وقــد جــرى االطــاع علــى الالئحــة ولــم أجــد فيهــا مــا‬\n‫يوجــب الرجــوع عمــا حكمــت بــه وأمــرت برفــع كامــل أوراق املعاملــة‬\n‫حملكمــة االســتئناف لتدقيــق احلكــم وأقفلــت اجللســة الســاعة التاســعة‬\n‫صباحــا وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n‫‪1434/07/19‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة‬\n‫الدائ ــرة اجلـزائي ــة الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية‬\n‫علــى املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/341877672‬ج‪ 2‬وتاريــخ‬\n‫‪1434/8/3‬ه ـ الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة‬\n‫األحســاء املكلــف برقــم ‪ 34/587421‬وتاريــخ ‪1434/7/25‬ه ـ املرفــق‬\n‫بهــا القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪.........../‬‬\n‫املســجل برقــم ‪ 34243663‬وتاريــخ ‪1434/6/18‬ه ـ اخلــاص بدعــوى‪/‬‬\n‫املدعــي العــام ضــد‪.........../‬يف قضيــة انتحــال شــخصية الغيــر وقــد‬\n‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                     ‫وصحبــه وســلم‪ .‬حــرر يف ‪1434/8/7‬هــ‪.‬‬\n\n\n\n\n                                                                                      ‫‪338‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":333,"source_page_end":338,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"aa03b38471392480f211b535d226daabf538a484929faf32f8f346a1034f386a","normalized_text_hash":"5cde2e7fb0705a9230fe514c3cea8e2638b6354ccec60c2b73dcdc3cce7f87d9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p333-34244363"}]$archive_payload$::jsonb) AS x LIMIT 25
